//! Signed tipster actions. (S-2.4) Message = DOMAIN_TAG ‖ borsh(SignedAction), verified with env::ed25519_verify.
//! Shared test vectors: fixtures/vectors.json (generated by `pnpm gen-vectors`; mirrored in packages/crypto).

use near_sdk::borsh::to_vec;
use near_sdk::json_types::Base64VecU8;
use near_sdk::{env, require};

use crate::errors::{E02_TIP_NOT_FOUND, E09_BAD_SIGNATURE, E10_BAD_NONCE};
use crate::types::{Action, CryptoHash, Ed25519PublicKey, ProgrammeId, SignedAction, TipId};
use crate::Contract;

pub const DOMAIN_TAG: &[u8] = b"sealedtip:v1";
pub const SUBMIT_TAG: &[u8] = b"sealedtip:v1:submit";

/// Bytes the tipster signs for every action: `DOMAIN_TAG ‖ borsh(SignedAction)`.
pub fn action_message(action: &SignedAction) -> Vec<u8> {
    let mut message = DOMAIN_TAG.to_vec();
    message.extend_from_slice(&to_vec(action).expect("BR01: borsh serialization failed"));
    message
}

/// Bytes the tipster signs at submission. The tip id does not exist yet, so it is not in the message.
/// Borsh encodes the tuple as concatenation: `u64le ‖ 32 bytes ‖ 32 bytes`.
pub fn submit_message(
    programme_id: ProgrammeId,
    evidence_hash: &CryptoHash,
    claim_pubkey: &Ed25519PublicKey,
) -> Vec<u8> {
    let mut message = SUBMIT_TAG.to_vec();
    message.extend_from_slice(&to_vec(&programme_id).expect("BR01: borsh serialization failed"));
    message.extend_from_slice(evidence_hash);
    message.extend_from_slice(claim_pubkey);
    message
}

/// Panics with E09 if the signature doesn't verify.
pub fn assert_signature(message: &[u8], signature: &Base64VecU8, pubkey: &Ed25519PublicKey) {
    let raw: &[u8] = &signature.0;
    require!(raw.len() == 64, E09_BAD_SIGNATURE);
    let sig: &[u8; 64] = raw.try_into().unwrap();
    require!(env::ed25519_verify(sig, message, pubkey), E09_BAD_SIGNATURE);
}

impl Contract {
    /// The two rules every tipster-signed entry point shares: the nonce is the next one (E10), then
    /// the signature (E09) — cheap check first, because an ed25519 verify is the expensive half of a
    /// refusal and these methods are reachable by any allow-listed relayer.
    ///
    /// The signed bytes are rebuilt from what the contract holds — this account, this tip id, this
    /// nonce, this action — rather than taken apart from something the caller supplied, so a
    /// signature minted for another deployment, another tip or another action fails E09 instead of
    /// being accepted and then reinterpreted. `SignedAction::contract` is inside the message for
    /// exactly that reason: the same bytes signed against a testnet copy of this contract must not
    /// verify against the mainnet one.
    ///
    /// The caller advances `tip.nonce` itself, once its own rules have passed. A call that reverts
    /// therefore consumes nothing, which is what lets a tipster retry after a relayer botches one.
    pub(crate) fn assert_signed(
        &self,
        tip_id: TipId,
        nonce: u64,
        action: Action,
        signature: &Base64VecU8,
    ) {
        let tip = self
            .tips
            .get(&tip_id)
            .unwrap_or_else(|| env::panic_str(E02_TIP_NOT_FOUND));
        // Exactly one ahead. `saturating_add` would let `u64::MAX` replay itself, and a replayable
        // action is the very thing the nonce exists to prevent.
        require!(nonce > tip.nonce && nonce - tip.nonce == 1, E10_BAD_NONCE);
        let message = action_message(&SignedAction {
            contract: env::current_account_id(),
            tip_id,
            nonce,
            action,
        });
        assert_signature(&message, signature, &tip.claim_pubkey);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::{Action, Payout, SignedAction};
    use near_sdk::AccountId;

    fn account(name: &str) -> AccountId {
        name.parse().unwrap()
    }

    fn checkin(nonce: u64) -> SignedAction {
        SignedAction {
            contract: account("sealedtip.hack.testnet"),
            tip_id: 1,
            nonce,
            action: Action::Checkin,
        }
    }

    /// Offset of the `Action` discriminant in a borsh-encoded `SignedAction`:
    /// `[u32 len][contract][u64 tip_id][u64 nonce][u8 action …]`.
    fn action_offset(contract: &str) -> usize {
        DOMAIN_TAG.len() + 4 + contract.len() + 8 + 8
    }

    #[test]
    fn message_is_domain_tag_prefixed_borsh() {
        let message = action_message(&checkin(3));
        assert_eq!(&message[..DOMAIN_TAG.len()], DOMAIN_TAG);
        // u64 LE tip_id, u64 LE nonce, u8 enum discriminant, no payload for Checkin.
        let expected_tail: [u8; 17] = [
            1, 0, 0, 0, 0, 0, 0, 0, // tip_id
            3, 0, 0, 0, 0, 0, 0, 0, // nonce
            0, // Action::Checkin
        ];
        let contract = b"sealedtip.hack.testnet";
        let mut expected = DOMAIN_TAG.to_vec();
        expected.extend_from_slice(&(contract.len() as u32).to_le_bytes());
        expected.extend_from_slice(contract);
        expected.extend_from_slice(&expected_tail);
        assert_eq!(message, expected);
    }

    #[test]
    fn claim_encodes_payout_inside_the_signed_action() {
        let action = SignedAction {
            contract: account("sealedtip.hack.testnet"),
            tip_id: 2,
            nonce: 1,
            action: Action::Claim {
                payout: Payout::Intents {
                    deposit_address: account("deposit.near"),
                    memo: None,
                },
            },
        };
        let message = action_message(&action);
        let decoded: SignedAction =
            near_sdk::borsh::from_slice(&message[DOMAIN_TAG.len()..]).unwrap();
        assert_eq!(decoded, action);
        // Action::Claim = 2, then Payout::Intents = 1, then [u32 len]address bytes, then memo: None.
        let at = action_offset("sealedtip.hack.testnet");
        assert_eq!(message[at], 2);
        assert_eq!(message[at + 1], 1);
        assert_eq!(&message[at + 2..at + 6], &12u32.to_le_bytes());
        assert_eq!(&message[at + 6..at + 18], b"deposit.near");
        assert_eq!(message[at + 18], 0);
        assert_eq!(message.len(), at + 19);
    }

    #[test]
    fn variant_order_matches_types_declaration() {
        // The wire format is positional: reordering Action or Payout silently breaks every
        // tipster signature. These are the discriminants fixtures/vectors.json encodes.
        let with = |a: Action| {
            let contract = "s.testnet";
            action_message(&SignedAction {
                contract: contract.parse().unwrap(),
                tip_id: 0,
                nonce: 0,
                action: a,
            })
        };
        assert_eq!(with(Action::Checkin)[action_offset("s.testnet")], 0);
        assert_eq!(with(Action::Retract)[action_offset("s.testnet")], 1);
        let claim = with(Action::Claim {
            payout: Payout::Near {
                account: "p.testnet".parse().unwrap(),
            },
        });
        let at = action_offset("s.testnet");
        assert_eq!(claim[at], 2); // Action::Claim
        assert_eq!(claim[at + 1], 0); // Payout::Near
    }

    #[test]
    fn submit_message_is_tagged_concatenation() {
        let hash = [7u8; 32];
        let pubkey = [9u8; 32];
        let message = submit_message(7, &hash, &pubkey);
        assert_eq!(&message[..SUBMIT_TAG.len()], SUBMIT_TAG);
        assert_eq!(
            &message[SUBMIT_TAG.len()..SUBMIT_TAG.len() + 8],
            &7u64.to_le_bytes()
        );
        assert_eq!(&message[SUBMIT_TAG.len() + 8..SUBMIT_TAG.len() + 40], &hash);
        assert_eq!(&message[SUBMIT_TAG.len() + 40..], &pubkey);
        assert_eq!(message.len(), SUBMIT_TAG.len() + 72);
    }

    #[test]
    fn short_signature_is_rejected() {
        let message = action_message(&checkin(1));
        let short = Base64VecU8(vec![0u8; 63]);
        let pubkey = [0u8; 32];
        let result = std::panic::catch_unwind(|| {
            assert_signature(&message, &short, &pubkey);
        });
        assert!(result.is_err());
    }

    // --- the shared signed-action rules (S-3.4, S-3.6) ---------------------------------------

    use crate::test_utils::{
        as_caller, contract_with, contract_with_tip, make_programme, relayer_1, sign_action,
        sign_action_at, tip_with_nonce,
    };

    /// What `submit_tip`'s relayer does with the bytes the tipster handed it.
    fn check(
        contract: &Contract,
        tip_id: TipId,
        nonce: u64,
        action: Action,
        signature: &Base64VecU8,
    ) {
        as_caller(relayer_1());
        contract.assert_signed(tip_id, nonce, action, signature);
    }

    #[test]
    fn an_action_signed_by_the_tipster_verifies() {
        // The mock host runs `env::ed25519_verify` for real, which is what lets a unit test reach the
        // rules *behind* a signature instead of only the ones in front of it.
        let contract = contract_with_tip();
        let signature = sign_action(0, 1, Action::Checkin);
        check(&contract, 0, 1, Action::Checkin, &signature);
    }

    #[test]
    #[should_panic(expected = "E09_BAD_SIGNATURE")]
    fn an_action_signed_for_another_contract_is_not_reused_here() {
        // Same tip, same nonce, same action — only the account inside the signed bytes differs. That
        // is the case `SignedAction::contract` exists for: a testnet signature must not be a mainnet
        // one.
        let contract = contract_with_tip();
        let signature = sign_action_at("sealedtip-copy.testnet", 0, 1, Action::Checkin);
        check(&contract, 0, 1, Action::Checkin, &signature);
    }

    #[test]
    #[should_panic(expected = "E09_BAD_SIGNATURE")]
    fn an_action_signed_for_another_tip_is_not_accepted_on_this_one() {
        let contract = contract_with_tip();
        let signature = sign_action(1, 1, Action::Checkin);
        check(&contract, 0, 1, Action::Checkin, &signature);
    }

    #[test]
    #[should_panic(expected = "E09_BAD_SIGNATURE")]
    fn a_checkin_signature_is_not_also_a_retraction() {
        // The action is inside the message, so the two cannot be traded for each other.
        let contract = contract_with_tip();
        let signature = sign_action(0, 1, Action::Checkin);
        check(&contract, 0, 1, Action::Retract, &signature);
    }

    #[test]
    #[should_panic(expected = "E10_BAD_NONCE")]
    fn a_replayed_nonce_is_refused() {
        // The tip's stored nonce is what a successful action leaves behind (S-3.4, S-3.6), so
        // presenting the nonce that already moved is a replay whatever it signs.
        let contract = contract_with(vec![make_programme()], vec![tip_with_nonce(1)]);
        let signature = sign_action(0, 1, Action::Checkin);
        check(&contract, 0, 1, Action::Checkin, &signature);
    }

    #[test]
    #[should_panic(expected = "E10_BAD_NONCE")]
    fn only_the_next_nonce_counts_not_a_later_one() {
        // A gap would let a relayer that missed one action use a signature made for a future one, and
        // it is the *sequence* that carries replay protection.
        let contract = contract_with_tip();
        let signature = sign_action(0, 7, Action::Checkin);
        check(&contract, 0, 7, Action::Checkin, &signature);
    }

    #[test]
    #[should_panic(expected = "E02_TIP_NOT_FOUND")]
    fn an_action_for_a_tip_that_does_not_exist_is_refused() {
        let contract = contract_with_tip();
        let signature = sign_action(4, 1, Action::Checkin);
        check(&contract, 4, 1, Action::Checkin, &signature);
    }

    #[test]
    fn a_tip_that_has_already_acted_carries_on_from_its_own_nonce() {
        let contract = contract_with(vec![make_programme()], vec![tip_with_nonce(1)]);
        let signature = sign_action(0, 2, Action::Checkin);
        check(&contract, 0, 2, Action::Checkin, &signature);
    }
}
